-- V016__seed_family_fixtures.sql
--
-- 家族种子收敛：把 msw fixtures 的全量种子搬进 SQL，成为唯一真源。
--
-- 背景（2026-08-29）
-- ============================================================================
-- 收敛前同一份「种子数据」有四套并存的 ID 体系：
--
--   msw JSON seeds        `...-0001-user-alice`（非法 UUID，PG 装不进去）
--   nextjs seed-db.mjs    resolveId() 把上面那串哈希成确定性 UUID
--   shared V014/V015      手写字面量（role `a00000000001` / app `1111...`）
--   aspnetcore InMemory   又一套（user `1000...` / role `2000...`）
--
-- 四套里只有 tenant acme（`...0001`）碰巧一致。后果：contract-test 无法逐字段
-- 比对四个后端的响应（ADR-0015），因为同一个 alice 在每个后端是不同的 id。
--
-- 对 saas_dev 实测到的真实状态（2026-08-29，只读核查）
-- ----------------------------------------------------------------------------
--   flyway_schema_history 只有 `<< Flyway Baseline >>` —— **V001..V015 从未被
--   Flyway 应用过**。库里的表结构与数据全部来自 nextjs 的 seed-db.mjs：
--     tenants 3（id 已是 canonical）/ roles 4、users 5、apps 3、menus 41 —— 全是哈希 UUID
--     menus 的 code 是 msw 那套（grp-biz / m-insp-spec…），不是 V015 的 m-overview 那套
--
--   即：数据库一直跟着 msw 走，V014/V015 是两份从未生效的 SQL。
--   故本迁移以 msw 全量种子为准（用户 2026-08-29 裁定），一并覆盖 V014/V015 的
--   app 与 menu 集合 —— 原计划的「菜单二期」在这里合并解决。
--
-- 本迁移确立的规范（可读 UUID 字面量，全合法 hex，沿用 V014 已开的头）
-- ----------------------------------------------------------------------------
--   tenants        00000000-0000-0000-0000-00000000000N   1=acme 2=globex 3=initech
--   roles          00000000-0000-0000-0000-a0000000000N   1=acme.admin（V014 已用此值）
--   users          00000000-0000-0000-0000-b0000000000N   1=alice … 5=eve
--   memberships    00000000-0000-0000-0000-c0000000000N   与 users 同序
--   api_keys       00000000-0000-0000-0000-d0000000000N
--   audit_events   00000000-0000-0000-0000-e0000000000N
--   permissions    00000000-0000-0000-0000-f0000000000N
--   menus          00000000-0000-0000-0000-9A0000000NNN   A=app 序号，NNN=app 内序号
--   apps           11111111-1111-1111-1111-11111111111N   1=lab-management（V014 已用）
--
-- 为什么是 TRUNCATE 而不是 ON CONFLICT（2026-08-29 用户裁定）
-- ----------------------------------------------------------------------------
-- 存量行的业务键（tenant+username / apps.client_id …）与本迁移相同，但 id 是哈希。
-- 「ON CONFLICT DO NOTHING + 固定 id」在这种库上是**静默跳过** —— 迁移报成功，
-- 数据却还是旧 id。这正是 lab 仓 V014/V015 撞号事故的形状。
-- demo/dev 种子可重灌，故 TRUNCATE 后全量写入，结果与库的历史状态无关。
--
-- apps 也必须进 TRUNCATE：它的 client_id 唯一约束会让 ON CONFLICT 跳过，
-- canonical app id 永远落不了地；而 menus.app_id / role_menu_grants 都挂在它下面。

-- ── 1. 清空：租户树 + 应用树 + 平台级权限 ─────────────────────────────────
-- CASCADE 连带清空 users / tenant_memberships / roles / role_permissions /
-- api_keys / audit_events / audit_retention_policies / menus / role_menu_grants。
-- 下面逐一重建，无一遗漏。

TRUNCATE TABLE tenants, apps, permissions CASCADE;

